  if exists (select 1 from public.genealogy_members where id = 'b3121df1-1781-5489-81e8-d520277beb0c') then raise exception 'Script déjà exécuté : rien n''a été fait.'; end if;
  -- Arbre « Han » (CHN)
  select id into top from public.dossier_sections where owner_type = 'country' and owner_id = 'CHN' and title = 'Dynastie' and parent_section_id is null and category_id = cat_id;
