    insert into public.dossier_sections (id, category_id, owner_type, owner_id, parent_section_id, title, position, created_by)
    values ('1d6e15a6-087f-54d5-b093-f26a528d4928', cat_id, 'country', 'CHN', top, 'Han', (select coalesce(max(position), -1) + 1 from public.dossier_sections where parent_section_id = top), admin_id);
    sec := '1d6e15a6-087f-54d5-b093-f26a528d4928';
  end if;
  insert into public.dossier_entries (id, owner_type, owner_id, type, title, category_id, section_id, created_by)
  values ('2ad01456-6dc6-5792-ac7d-8b8f8d6feb16', 'country', 'CHN', 'genealogy', 'Han', cat_id, sec, admin_id);
